class CinbaseServiceConfigTests(unittest.TestCase):
    """Starting a cinbase backend must not reset the shared config singleton."""

    def setUp(self):
        self.old_appdata = os.environ.get("APPDATA")
        self.old_cwd = os.getcwd()
        self.temp_dir = tempfile.TemporaryDirectory(prefix="pime-cin-config-")
        os.environ["APPDATA"] = self.temp_dir.name
        os.chdir(self.temp_dir.name)

    def tearDown(self):
        os.chdir(self.old_cwd)
        if self.old_appdata is None:
            os.environ.pop("APPDATA", None)
        else:
            os.environ["APPDATA"] = self.old_appdata
        self.temp_dir.cleanup()

    def test_service_startup_does_not_reset_the_shared_singleton(self):
        from cinbase import config as cinbase_config

        shared = cinbase_config.CinBaseConfig
        shared.candPerRow = 9
        shared.defaultEnglish = True

        from input_methods.checj import checj_ime
        service = checj_ime.CheCJTextService(ime_smoke_runner.FakeClient())

        # Constructing the backend used to call CinBaseConfig.__init__() on
        # the shared singleton, snapping these back to the defaults.
        self.assertEqual(shared.candPerRow, 9)
        self.assertTrue(shared.defaultEnglish)

        # The service keeps a private config, still wired to its own IME.
        self.assertIsNot(service.cfg, shared)
        self.assertEqual(service.cfg.imeDirName, "checj")
        self.assertEqual(service.configVersion, service.cfg.getVersion())

    def test_two_service_instances_do_not_share_config(self):
        from input_methods.checj import checj_ime

        first = checj_ime.CheCJTextService(ime_smoke_runner.FakeClient())
        second = checj_ime.CheCJTextService(ime_smoke_runner.FakeClient())

        self.assertIsNot(first.cfg, second.cfg)
        first.cfg.switchLangWithShift = False
        self.assertTrue(second.cfg.switchLangWithShift)


